function registrarAtividade(){if(!usuarioAtual)return;const agora=Date.now();if(agora-ultimaAtividade<1000)return;ultimaAtividade=agora;programarSaida();const intervaloPing=Math.min(5*60*1000,Math.max(30*1000,minutosOciosidade*30*1000));if(agora-ultimoPing>=intervaloPing){ultimoPing=agora;fetch("/api/sessao").then(r=>{if(r.status===401)exibirLogin("Sua sessão expirou. Entre novamente.")}).catch(()=>{})}}
