function iniciarPresenca(){clearInterval(timerPresenca);const enviar=()=>{if(!usuarioAtual||document.visibilityState!=="visible"||Date.now()-ultimaAtividade>=minutosOciosidade*60*1000)return;fetch("/api/presenca",{method:"POST",headers:{"Content-Type":"application/json"}}).then(r=>{if(r.status===401)exibirLogin("Sua sessão expirou. Entre novamente.")}).catch(()=>{})};enviar();timerPresenca=setInterval(enviar,15000)}
