async function api(url,options={}){const r=await fetch(url,{headers:{"Content-Type":"application/json"},...options});let j={};try{j=await r.json()}catch{}if(r.status===401&&url!=="/api/login"){exibirLogin("Sua sessão expirou. Entre novamente.");throw new Error("Sessão expirada.")}if(!r.ok)throw new Error(j.erro||"Erro na operação");return j}
