function duracaoSessao(segundos){const total=Math.max(0,Number(segundos)||0),dias=Math.floor(total/86400),horas=Math.floor(total%86400/3600),minutos=Math.floor(total%3600/60),segs=Math.floor(total%60);return dias?`${dias}d ${String(horas).padStart(2,"0")}h ${String(minutos).padStart(2,"0")}m`:horas?`${horas}h ${String(minutos).padStart(2,"0")}m ${String(segs).padStart(2,"0")}s`:`${minutos}m ${String(segs).padStart(2,"0")}s`}
async function carregarSessoesAtivas(){if(telaAtual!=="painel"||usuarioAtual?.perfil!=="administrador")return;const area=$("#usuariosLogados");if(!area)return;try{const d=await api("/api/sistema/sessoes");if(!$("#usuariosLogados"))return;area.innerHTML=`<div class="sessoes-topo"><div><h3>Usuários logados em tempo real</h3><p>Atualização automática a cada 5 segundos.</p></div><div class="sessoes-contadores"><span><b>${h(d.online)}</b> online</span><span><b>${h(d.total)}</b> sessões</span></div></div>${d.sessoes.length?`<div class="tabela-wrap"><table class="tabela-sessoes"><thead><tr><th>Usuário</th><th>Status</th><th>Dispositivo</th><th>Entrada</th><th>Duração</th><th>Última presença</th></tr></thead><tbody>${d.sessoes.map(s=>`<tr><td><b>${h(s.usuario.nome)}</b>${s.sessao_atual?'<span class="sessao-atual">Esta sessão</span>':""}<br><small>${h(perfis[s.usuario.perfil]||s.usuario.perfil)} · ${h(s.usuario.usuario||s.usuario.email)}</small></td><td><span class="presenca ${s.status}">${s.status==="online"?"Online":"Ocioso"}</span>${s.status==="ocioso"?`<br><small>há ${h(duracaoSessao(s.ocioso_segundos))}</small>`:""}</td><td>${h(s.dispositivo)}<br><small>IP: ${h(s.ip)}</small></td><td>${h(dataHoraBr(s.login_em))}</td><td><b>${h(duracaoSessao(s.duracao_segundos))}</b><br><small>Expira em ${h(duracaoSessao(s.restante_segundos))} se permanecer ociosa</small></td><td>${h(dataHoraBr(s.ultima_presenca))}</td></tr>`).join("")}</tbody></table></div>`:'<p class="vazio">Nenhum usuário conectado.</p>'}`}catch(e){if($("#usuariosLogados"))area.innerHTML=`<h3>Usuários logados em tempo real</h3><p class="erro-sessoes">${h(e.message)}</p>`}}
