function renderPreviaImportacao(){const area=$("#previaImportacao");if(!area)return;const validos=importacaoInteressados.filter(x=>x.valido),invalidos=importacaoInteressados.length-validos.length;area.innerHTML=`<div class="importacao-previa"><div class="importacao-topo"><div><h3>Conferência da planilha</h3><p><b>${validos.length}</b> registro(s) pronto(s) para importar${invalidos?` e <b>${invalidos}</b> linha(s) incompleta(s), que não serão importadas`:""}.</p></div><button type="button" class="secundario" id="cancelarImportacao">Cancelar</button></div><div class="tabela-wrap"><table><thead><tr><th>Linha</th><th>Aluno</th><th>Responsável</th><th>Telefone</th><th>Turma</th><th>Resultado</th></tr></thead><tbody>${importacaoInteressados.slice(0,20).map(x=>`<tr><td>${h(x.linha)}</td><td>${h(x.aluno_nome||"—")}</td><td>${h(x.responsavel_nome||"—")}</td><td>${h(x.telefone||"—")}</td><td>${h(x.turma_interesse||"A definir")}</td><td><span class="status ${x.valido?"importacao-ok":"importacao-erro"}">${x.valido?"Pronto":"Revisar"}</span></td></tr>`).join("")}</tbody></table></div>${importacaoInteressados.length>20?`<small>Prévia das primeiras 20 linhas de ${importacaoInteressados.length}.</small>`:""}<div class="importacao-acoes"><button type="button" id="confirmarImportacao" ${validos.length?"":"disabled"}>Importar ${validos.length} interessado(s)</button></div></div>`;$("#cancelarImportacao").onclick=()=>{importacaoInteressados=[];area.innerHTML=""};$("#confirmarImportacao").onclick=confirmarImportacaoInteressados}
async function confirmarImportacaoInteressados(){const botao=$("#confirmarImportacao"),registros=importacaoInteressados.filter(x=>x.valido).map(({valido,linha,...x})=>x);if(!registros.length)return;botao.disabled=true;botao.textContent="Importando...";try{const r=await api("/api/interessados/importar",{method:"POST",body:JSON.stringify({registros})});alert(`Importação concluída.\n\nImportados: ${r.importados}\nDuplicados ignorados: ${r.duplicados}\nInválidos: ${r.invalidos}`);importacaoInteressados=[];await telaInteressados()}catch(e){alert(e.message);botao.disabled=false;botao.textContent=`Importar ${registros.length} interessado(s)`}}
async function telaInteressados(){telaAtual="interessados";$("#titulo").textContent="Interessados";const acoes=podeEditar()?'<div class="toolbar-acoes"><button id="baixarModeloInteressados" type="button" class="secundario">Baixar modelo CSV</button><button id="importarInteressados" type="button">Importar CSV</button><input id="arquivoInteressados" class="oculto" type="file" accept=".csv,text/csv"></div>':"";$("#conteudo").innerHTML=`<div class="bloco"><div class="toolbar"><input id="buscaInteressado" placeholder="Pesquisar aluno, responsável ou telefone"><select id="filtroStatus"><option value="">Todas as etapas</option>${Object.entries(etapas).map(([v,t])=>`<option value="${v}">${t}</option>`).join("")}</select>${acoes}</div><div id="previaImportacao"></div><div id="resultadoInteressados"></div></div>`;$("#buscaInteressado").oninput=()=>{clearTimeout(timerBusca);timerBusca=setTimeout(carregarInteressados,250)};$("#filtroStatus").onchange=carregarInteressados;if(podeEditar()){$("#baixarModeloInteressados").onclick=baixarModeloInteressados;$("#importarInteressados").onclick=()=>$("#arquivoInteressados").click();$("#arquivoInteressados").onchange=e=>prepararImportacaoInteressados(e.target.files[0])}await carregarInteressados()}
