async function telaMatriculas(){telaAtual="matriculas";$("#titulo").textContent="Matrículas";const rows=await api("/api/matriculas"),professor=usuarioAtual?.perfil==="professor";$("#conteudo").innerHTML=`<div class="bloco"><h3>Matrículas realizadas</h3>${rows.length?`<div class="tabela-wrap"><table><thead><tr><th>Aluno</th><th>Turma</th><th>Ano</th>${professor?"":"<th>Responsável</th><th>Plano</th>"}<th>Status</th>${podeVerContrato()?"<th>Contrato</th>":""}${podeEditar()?"<th>Ações</th>":""}</tr></thead><tbody>${rows.map(x=>`<tr><td><b>${h(x.aluno_nome)}</b></td><td>${h(x.turma)}</td><td>${h(x.ano_letivo)}</td>${professor?"":`<td>${h(x.responsavel_nome)}</td><td>${h(x.plano_horas)}</td>`}<td><span class="status">${h(x.status)}</span></td>${podeVerContrato()?`<td>${x.contrato_id?`<a class="contrato-link" href="/api/contratos/${x.contrato_id}/pdf" target="_blank">Abrir PDF</a>`:"—"}</td>`:""}${podeEditar()?`<td><div class="acoes"><button class="acao editar" data-editar-matricula="${x.id}">Ver/editar</button>${usuarioAtual?.perfil==="administrador"?`<button class="acao excluir" data-excluir-matricula="${x.id}" data-nome="${h(x.aluno_nome)}">Excluir</button>`:""}</div></td>`:""}</tr>`).join("")}</tbody></table></div>`:'<p class="vazio">Nenhuma matrícula cadastrada.</p>'}</div>`}
async function telaFinanceiro(){telaAtual="financeiro";$("#titulo").textContent="Financeiro";const ano=new Date().getFullYear();$("#conteudo").innerHTML=`<div class="bloco"><div class="toolbar financeiro-filtros"><input id="buscaFinanceiro" placeholder="Pesquisar aluno ou responsável"><input id="anoFinanceiro" type="number" min="2020" max="2100" value="${ano}"><select id="statusFinanceiro"><option value="">Todas as situações</option><option value="pendente">Em aberto</option><option value="atrasado">Atrasadas</option><option value="pago">Pagas</option><option value="cancelado">Canceladas</option></select></div></div><div id="resultadoFinanceiro"></div>`;let timer;$("#buscaFinanceiro").oninput=()=>{clearTimeout(timer);timer=setTimeout(carregarFinanceiro,250)};$("#anoFinanceiro").onchange=carregarFinanceiro;$("#statusFinanceiro").onchange=carregarFinanceiro;await carregarFinanceiro()}
function adicionarExportacaoFinanceiro(){if(!["administrador","direcao","financeiro"].includes(usuarioAtual?.perfil))return;const barra=$(".financeiro-filtros");if(!barra||$("#exportarFinanceiro"))return;const acoes=document.createElement("div");acoes.id="exportarFinanceiro";acoes.className="relatorios-financeiro";acoes.innerHTML='<button type="button" class="secundario" data-relatorio="pdf">Relatório PDF</button><button type="button" data-relatorio="csv">Exportar para Excel</button>';acoes.onclick=e=>{const tipo=e.target.dataset.relatorio;if(!tipo)return;const p=new URLSearchParams({ano:$("#anoFinanceiro").value,q:$("#buscaFinanceiro").value,status:$("#statusFinanceiro").value}),url=`/api/financeiro/relatorio.${tipo}?${p}`;if(tipo==="pdf")window.open(url,"_blank","noopener");else window.location.href=url};barra.parentElement.appendChild(acoes)}
function mensagemCobrancaWhatsapp(x){const referencia=x.tipo==="matricula"?`matrícula referente ao ano letivo de ${x.ano_letivo}`:`mensalidade de ${meses[Number(x.parcela_numero)]} de ${x.ano_letivo}`,atrasada=x.status_exibicao==="atrasado",inicio=atrasada?`Identificamos que a ${referencia} do(a) aluno(a) ${x.aluno_nome}, com vencimento em ${dataBr(x.vencimento)}, no valor de ${dinheiro(x.valor_atual)}, encontra-se em aberto.`:`Passando para lembrar que a ${referencia} do(a) aluno(a) ${x.aluno_nome}, no valor de ${dinheiro(x.valor_atual)}, tem vencimento em ${dataBr(x.vencimento)}.`;return `Olá, ${x.responsavel_nome}! Tudo bem?\n\n${inicio}\n\nCaso o pagamento já tenha sido realizado, por favor desconsidere esta mensagem.\n\nAtenciosamente,\nColégio Horizonte.`}
function linkCobrancaWhatsapp(x){const numero=telefoneWhats(x.responsavel_telefone);return numero?`https://wa.me/${numero}?text=${encodeURIComponent(mensagemCobrancaWhatsapp(x))}`:""}
async function carregarFinanceiro(){const ano=$("#anoFinanceiro")?.value||new Date().getFullYear(),q=$("#buscaFinanceiro")?.value||"",status=$("#statusFinanceiro")?.value||"",d=await api(`/api/financeiro?ano=${encodeURIComponent(ano)}&q=${encodeURIComponent(q)}&status=${encodeURIComponent(status)}`),r=d.resumo,labels={pendente:"Em aberto",atrasado:"Atrasada",pago:"Paga",cancelado:"Cancelada"};if(!$("#resultadoFinanceiro"))return;$("#resultadoFinanceiro").innerHTML=`<div class="cards cards-financeiro"><div class="card"><span>Recebido</span><strong>${dinheiro(r.recebido)}</strong></div><div class="card"><span>Em aberto</span><strong>${dinheiro(r.aberto)}</strong></div><div class="card card-atraso"><span>Atrasado (${r.quantidade_atrasada})</span><strong>${dinheiro(r.atrasado)}</strong></div></div><div class="bloco"><h3>Cobranças de ${h(d.ano)}</h3>${d.cobrancas.length?`<div class="tabela-wrap"><table><thead><tr><th>Aluno</th><th>Cobrança</th><th>Vencimento</th><th>Valor</th><th>Situação</th><th>Pagamento</th><th>Ação</th></tr></thead><tbody>${d.cobrancas.map(x=>{const link=x.status==="pendente"?linkCobrancaWhatsapp(x):"";return `<tr><td><b>${h(x.aluno_nome)}</b><br><small>${h(x.responsavel_nome)}</small></td><td>${x.tipo==="matricula"?"Matrícula":`${meses[Number(x.parcela_numero)]} · ${x.parcela_numero}/12`}</td><td>${dataBr(x.vencimento)}</td><td><b>${dinheiro(x.valor_atual)}</b>${Number(x.desconto)>0?`<br><small>Desconto: ${dinheiro(x.desconto)}</small>`:""}${Number(x.acrescimo)>0?`<br><small>Acréscimo: ${dinheiro(x.acrescimo)}</small>`:""}</td><td><span class="status financeiro-${x.status_exibicao}">${labels[x.status_exibicao]}</span></td><td>${x.status==="pago"?`${dataBr(x.pago_em)}<br><small>${h(x.forma_pagamento||"")} · ${dinheiro(x.valor_pago)}</small>`:"—"}</td><td><div class="acoes acoes-financeiro"><button class="acao editar" data-editar-cobranca='${h(JSON.stringify(x))}'>Atualizar</button>${link?`<a class="acao cobranca-whatsapp" href="${h(link)}" target="_blank" rel="noopener">WhatsApp</a>`:x.status==="pendente"?'<small class="sem-whatsapp">Sem telefone</small>':""}</div></td></tr>`}).join("")}</tbody></table></div>`:'<p class="vazio">Nenhuma cobrança encontrada para os filtros selecionados.</p>'}</div>`}
function editarCobranca(x){const f=$("#financeiroForm"),preencher=(n,v)=>f.elements[n].value=v??"";f.reset();preencher("id",x.id);preencher("desconto",x.desconto);preencher("acrescimo",x.acrescimo);preencher("status",x.status);preencher("valor_pago",x.valor_pago||x.valor_atual);preencher("pago_em",String(x.pago_em||new Date().toISOString()).slice(0,10));preencher("forma_pagamento",x.forma_pagamento);preencher("observacoes",x.observacoes);reciboFinanceiro.href=`/api/financeiro/${x.id}/recibo`;reciboFinanceiro.classList.toggle("oculto",x.status!=="pago");$("#financeiroTitulo").textContent=`Cobrança: ${x.aluno_nome}`;$("#financeiroDescricao").textContent=`${x.tipo==="matricula"?"Matrícula":meses[Number(x.parcela_numero)]} · vencimento ${dataBr(x.vencimento)} · valor original ${dinheiro(x.valor_original)}`;$("#financeiroModal").showModal()}
