async function telaEquipe(){telaAtual="equipe";$("#titulo").textContent="Equipe e acessos";const rows=await api("/api/usuarios");$("#conteudo").innerHTML=`<div class="bloco equipe-grid"><form id="usuarioForm" class="usuario-form"><input name="id" type="hidden"><h3 id="usuarioFormTitulo">Novo usuário</h3><label>Nome completo<input name="nome" required></label><label>E-mail<input name="email" type="email" required></label><label>Nome de usuário<input name="usuario" minlength="3" maxlength="40" placeholder="Ex.: patricia" autocomplete="off" required></label><label>CPF<input name="cpf" inputmode="numeric" maxlength="14" placeholder="000.000.000-00" required></label><label>Perfil<select name="perfil" required>${Object.entries(perfis).map(([v,t])=>`<option value="${v}">${t}</option>`).join("")}</select></label><div id="perfilAjuda" class="perfil-ajuda" aria-live="polite"></div><label>Status<select name="ativo"><option value="true">Ativo</option><option value="false">Inativo</option></select></label><label>Senha<input name="senha" type="password" minlength="8" autocomplete="new-password" placeholder="Mínimo de 8 caracteres"></label><label>Repetir senha<input name="confirmar_senha" type="password" minlength="8" autocomplete="new-password" placeholder="Digite a mesma senha novamente"></label><small id="senhaAjuda">As duas senhas são obrigatórias no primeiro cadastro.</small><div class="acoes-form"><button type="button" class="secundario" id="cancelarUsuario">Limpar</button><button>Salvar usuário</button></div></form><section><h3>Usuários cadastrados</h3><div class="tabela-wrap"><table><thead><tr><th>Nome</th><th>Acessos</th><th>Perfil</th><th>Status</th><th>Ação</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${h(x.nome)}</b></td><td>${h(x.email)}<br><small>@${h(x.usuario||"não definido")} · CPF: ${h(cpfExibicao(x.cpf)||"não definido")}</small></td><td>${h(perfis[x.perfil]||x.perfil)}</td><td><span class="status ${x.ativo?"":"inativo"}">${x.ativo?"Ativo":"Inativo"}</span></td><td><div class="acoes"><button class="acao editar" data-editar-usuario='${h(JSON.stringify(x))}'>Editar</button>${x.ativo?`<button class="acao redefinir" data-redefinir-senha="${x.id}" data-nome="${h(x.nome)}">Redefinir senha</button>`:""}</div></td></tr>`).join("")}</tbody></table></div></section></div>`;const form=$("#usuarioForm"),senha=form.elements.senha,confirmacao=form.elements.confirmar_senha,perfil=form.elements.perfil;const atualizarPerfil=()=>{$("#perfilAjuda").innerHTML=`<b>${h(perfis[perfil.value])}</b><span>${h(descricoesPerfis[perfil.value])}</span>`};perfil.addEventListener("change",atualizarPerfil);atualizarPerfil();const validarSenhas=()=>confirmacao.setCustomValidity(senha.value===confirmacao.value?"":"As senhas não são iguais.");senha.addEventListener("input",validarSenhas);confirmacao.addEventListener("input",validarSenhas);form.elements.cpf.addEventListener("input",e=>{e.target.value=cpfExibicao(e.target.value)});const limpar=()=>{form.reset();form.elements.id.value="";$("#usuarioFormTitulo").textContent="Novo usuário";$("#senhaAjuda").textContent="As duas senhas são obrigatórias no primeiro cadastro.";atualizarPerfil()};$("#cancelarUsuario").onclick=limpar;form.onsubmit=async e=>{e.preventDefault();validarSenhas();if(!form.reportValidity())return;const body=Object.fromEntries(new FormData(form)),id=body.id;delete body.id;body.ativo=body.ativo==="true";try{await api(id?`/api/usuarios/${id}`:"/api/usuarios",{method:id?"PUT":"POST",body:JSON.stringify(body)});await telaEquipe()}catch(err){alert(err.message)}}}
