async function abrirMatricula(id){try{const {interessado:x}=await api(`/api/interessados/${id}`),f=$("#matriculaForm");f.reset();f.elements.matricula_id.value="";f.elements.interessado_id.value=x.id;f.elements.aluno_nome.value=x.aluno_nome||"";f.elements.turma.value=normalizarTurma(x.turma_interesse);f.elements.ano_letivo.value=new Date().getFullYear()+1;f.elements.responsavel_nome.value=x.responsavel_nome||"";f.elements.responsavel_telefone.value=x.telefone||"";f.elements.responsavel_email.value=x.email||"";f.elements.plano_horas.value=x.plano_horas||"";f.elements.entrada.value=x.entrada?String(x.entrada).slice(0,5):"";f.elements.saida.value=x.saida?String(x.saida).slice(0,5):"";f.elements.vencimento_dia.value=5;$("#matriculaTitulo").textContent="Converter em matrícula";$("#matriculaDescricao").textContent="Os dados já cadastrados foram reaproveitados. Confira antes de concluir.";$("#matriculaSalvar").textContent="Concluir matrícula e gerar contrato";atualizarDuracaoPlano();if($("#modal").open)$("#modal").close();$("#matriculaModal").showModal()}catch(err){alert(err.message)}}
async function editarMatricula(id){try{const d=await api(`/api/matriculas/${id}`),x=d.matricula,r1=d.responsaveis.find(r=>Number(r.ordem)===1)||{},r2=d.responsaveis.find(r=>Number(r.ordem)===2)||{},f=$("#matriculaForm");f.reset();const preencher=(nome,valor)=>{if(f.elements[nome])f.elements[nome].value=valor==null?"":valor};preencher("matricula_id",x.id);preencher("interessado_id",x.interessado_id);preencher("aluno_nome",x.aluno_nome);preencher("aluno_nascimento",String(x.aluno_nascimento||"").slice(0,10));preencher("aluno_cpf",x.aluno_cpf);preencher("ano_letivo",x.ano_letivo);preencher("turma",normalizarTurma(x.turma));preencher("responsavel_nome",r1.nome);preencher("responsavel_cpf",r1.cpf);preencher("responsavel_rg",r1.rg);preencher("responsavel_telefone",r1.telefone);preencher("responsavel_email",r1.email);preencher("responsavel_endereco",r1.endereco);preencher("parentesco",r1.parentesco);preencher("responsavel2_nome",r2.nome);preencher("responsavel2_cpf",r2.cpf);preencher("responsavel2_rg",r2.rg);preencher("responsavel2_telefone",r2.telefone);preencher("responsavel2_email",r2.email);preencher("responsavel2_endereco",r2.endereco);preencher("responsavel2_parentesco",r2.parentesco);preencher("responsavel_financeiro",r2.financeiro?"2":"1");preencher("responsavel_assinante",r2.assinante?"2":"1");preencher("plano_horas",x.plano_horas);preencher("entrada",String(x.entrada||"").slice(0,5));preencher("saida",String(x.saida||"").slice(0,5));preencher("mensalidade",x.mensalidade);preencher("vencimento_dia",x.vencimento_dia);$("#matriculaTitulo").textContent=`Editar matrícula: ${x.aluno_nome}`;$("#matriculaDescricao").textContent=`Contrato ${d.contrato?.numero||""}. As correções aparecerão automaticamente no PDF.`;$("#matriculaSalvar").textContent="Salvar alterações";atualizarDuracaoPlano();$("#matriculaModal").showModal()}catch(err){alert(err.message)}}
async function excluirInteressado(id,nome){const origem=telaAtual,confirmacao=prompt(`Para excluir permanentemente o cadastro de ${nome}, digite EXCLUIR.`);if(confirmacao!=="EXCLUIR")return;try{const r=await api(`/api/interessados/${id}`,{method:"DELETE"});alert(`Cadastro excluído.\n\nBackup de segurança: ${r.arquivo_backup}`);if(origem==="painel")await painel();else await telaInteressados()}catch(e){alert(e.message)}}
