$("#leadForm").onsubmit=async e=>{e.preventDefault();const form=Object.fromEntries(new FormData(e.target)),id=form.id;delete form.id;try{await api(id?`/api/interessados/${id}`:"/api/interessados",{method:id?"PUT":"POST",body:JSON.stringify(form)});$("#modal").close();if(telaAtual==="interessados")await telaInteressados();else await painel()}catch(err){alert(err.message)}};
$("#contatoForm").onsubmit=async e=>{e.preventDefault();const form=Object.fromEntries(new FormData(e.target)),id=form.interessado_id;delete form.interessado_id;try{await api(`/api/interessados/${id}/contatos`,{method:"POST",body:JSON.stringify(form)});e.target.elements.resumo.value="";e.target.elements.proximo_contato.value="";await editarInteressado(id)}catch(err){alert(err.message)}};
$("#matriculaForm").onsubmit=async e=>{e.preventDefault();const form=Object.fromEntries(new FormData(e.target)),id=form.matricula_id;delete form.matricula_id;try{const r=await api(id?`/api/matriculas/${id}`:"/api/matriculas",{method:id?"PUT":"POST",body:JSON.stringify(form)});$("#matriculaModal").close();alert(id?`Matrícula atualizada. O contrato ${r.contrato.numero} já está com os dados corrigidos.`:`Matrícula concluída. Contrato ${r.contrato.numero} gerado para conferência.`);$$('nav button').forEach(x=>x.classList.toggle("ativo",x.dataset.tela==="matriculas"));await telaMatriculas()}catch(err){alert(err.message)}};
$("#financeiroForm").onsubmit=async e=>{e.preventDefault();const form=Object.fromEntries(new FormData(e.target)),id=form.id;delete form.id;try{await api(`/api/financeiro/${id}`,{method:"PUT",body:JSON.stringify(form)});$("#financeiroModal").close();await carregarFinanceiro()}catch(err){alert(err.message)}};
$("#redefinirSenhaForm").onsubmit=async e=>{e.preventDefault();const f=e.target,senha=f.elements.senha,confirmacao=f.elements.confirmar_senha,erro=$("#redefinirSenhaErro");confirmacao.setCustomValidity(senha.value===confirmacao.value?"":"As senhas não são iguais.");if(!f.reportValidity())return;erro.textContent="";const id=f.elements.usuario_id.value,botao=f.querySelector('button[type="submit"],button:not([type])');botao.disabled=true;try{const r=await api(`/api/usuarios/${id}/redefinir-senha`,{method:"POST",body:JSON.stringify({senha:senha.value,confirmar_senha:confirmacao.value})});$("#senhaModal").close();alert(`Senha de ${r.nome} redefinida com sucesso. As outras sessões desse usuário foram encerradas.`)}catch(err){erro.textContent=err.message}finally{botao.disabled=false}};
$("#minhaContaForm").onsubmit=async e=>{e.preventDefault();const f=e.target,senha=f.elements.senha,confirmacao=f.elements.confirmar_senha,erro=$("#minhaContaErro");confirmacao.setCustomValidity(senha.value===confirmacao.value?"":"As senhas não são iguais.");if(!f.reportValidity())return;erro.textContent="";const botao=f.querySelector('button[type="submit"],button:not([type])');botao.disabled=true;try{await api("/api/minha-conta/senha",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(f)))});$("#minhaContaModal").close();alert("Sua senha foi alterada com sucesso. As outras sessões da sua conta foram encerradas.")}catch(err){erro.textContent=err.message}finally{botao.disabled=false}};
$("#conteudo").addEventListener("click",e=>{const editar=e.target.closest("[data-editar]"),converter=e.target.closest("[data-converter]"),editarMat=e.target.closest("[data-editar-matricula]"),editarUsuario=e.target.closest("[data-editar-usuario]"),redefinirSenha=e.target.closest("[data-redefinir-senha]"),excluirInt=e.target.closest("[data-excluir-interessado]"),excluirMat=e.target.closest("[data-excluir-matricula]");if(editar)editarInteressado(editar.dataset.editar);if(converter)abrirMatricula(converter.dataset.converter);if(editarMat)editarMatricula(editarMat.dataset.editarMatricula);if(redefinirSenha)abrirRedefinicaoSenha(redefinirSenha.dataset.redefinirSenha,redefinirSenha.dataset.nome);if(excluirInt)excluirInteressado(excluirInt.dataset.excluirInteressado,excluirInt.dataset.nome);if(excluirMat)excluirMatricula(excluirMat.dataset.excluirMatricula,excluirMat.dataset.nome);if(editarUsuario){const x=JSON.parse(editarUsuario.dataset.editarUsuario),f=$("#usuarioForm");f.elements.id.value=x.id;f.elements.nome.value=x.nome;f.elements.email.value=x.email;f.elements.usuario.value=x.usuario||"";f.elements.cpf.value=cpfExibicao(x.cpf);f.elements.perfil.value=x.perfil;f.elements.perfil.dispatchEvent(new Event("change"));f.elements.ativo.value=String(x.ativo);f.elements.senha.value="";f.elements.confirmar_senha.value="";$("#usuarioFormTitulo").textContent=`Editar: ${x.nome}`;$("#senhaAjuda").textContent="Para manter a senha atual, deixe os dois campos de senha vazios.";f.scrollIntoView({behavior:"smooth",block:"start"})}});
$("#conteudo").addEventListener("click",e=>{const editarFinanceiro=e.target.closest("[data-editar-cobranca]");if(editarFinanceiro)editarCobranca(JSON.parse(editarFinanceiro.dataset.editarCobranca))});
$$('nav button').forEach(b=>b.onclick=async()=>{clearInterval(timerSessoes);$$('nav button').forEach(x=>x.classList.remove("ativo"));b.classList.add("ativo");const tela=b.dataset.tela;if(tela==="painel")return painel();if(tela==="interessados")return telaInteressados();if(tela==="matriculas")return telaMatriculas();if(tela==="financeiro")return telaFinanceiro();if(tela==="contratos")return telaContratos();if(tela==="equipe")return telaEquipe();if(tela==="auditoria")return telaAuditoria();if(tela==="backup")return telaBackup();if(tela==="rede")return telaRede()});
document.querySelector('[data-tela="financeiro"]').addEventListener("click",()=>setTimeout(adicionarExportacaoFinanceiro,0));
const acoesAuditoria={cadastro_criado:"Interessado criado",cadastro_importado:"Interessado importado",cadastro_atualizado:"Interessado atualizado",contato_registrado:"Contato registrado",matricula_criada:"Matrícula criada",matricula_atualizada:"Matrícula atualizada",cobranca_atualizada:"Cobrança atualizada",usuario_criado:"Usuário criado",usuario_atualizado:"Usuário atualizado",senha_redefinida:"Senha redefinida",senha_alterada:"Senha alterada",interessado_excluido:"Interessado excluído",matricula_excluida:"Matrícula excluída"};
const tiposAuditoria={interessado:"Interessado",matricula:"Matrícula",cobranca:"Cobrança",usuario:"Usuário",exclusao:"Exclusão"};
function renderAuditoria(d){const p=d.paginacao;$("#resultadoAuditoria").innerHTML=`<div class="auditoria-resumo"><b>${h(p.total)}</b> registro(s) encontrado(s)</div>${d.registros.length?`<div class="tabela-wrap"><table class="tabela-auditoria"><thead><tr><th>Data e hora</th><th>Usuário</th><th>Ação</th><th>Cadastro</th><th>Detalhes</th></tr></thead><tbody>${d.registros.map(x=>`<tr><td>${h(dataHoraBr(x.criado_em))}</td><td><b>${h(x.usuario_nome)}</b><br><small>${h(perfis[x.usuario_perfil]||x.usuario_perfil||"Sistema")}</small></td><td><span class="auditoria-acao ${x.tipo_entidade==="exclusao"?"perigo":""}">${h(acoesAuditoria[x.acao]||x.acao.replaceAll("_"," "))}</span></td><td><b>${h(x.entidade_nome)}</b><br><small>${h(tiposAuditoria[x.tipo_entidade]||x.tipo_entidade)} · ID ${h(x.entidade_id)}</small></td><td>${h(x.detalhes||"Sem detalhes")}</td></tr>`).join("")}</tbody></table></div>`:'<p class="vazio">Nenhum registro encontrado para os filtros selecionados.</p>'}<div class="auditoria-paginacao"><button type="button" class="secundario" data-pagina-auditoria="${p.pagina-1}" ${p.pagina<=1?"disabled":""}>← Anterior</button><span>Página <b>${h(p.pagina)}</b> de <b>${h(p.total_paginas)}</b></span><button type="button" class="secundario" data-pagina-auditoria="${p.pagina+1}" ${p.pagina>=p.total_paginas?"disabled":""}>Próxima →</button></div>`;$$('[data-pagina-auditoria]').forEach(b=>b.onclick=()=>carregarAuditoria(Number(b.dataset.paginaAuditoria)))}
async function carregarAuditoria(pagina=1){const params=new URLSearchParams({pagina:String(pagina),q:$("#buscaAuditoria")?.value||"",tipo:$("#tipoAuditoria")?.value||"",usuario_id:$("#usuarioAuditoria")?.value||"",data_inicio:$("#inicioAuditoria")?.value||"",data_fim:$("#fimAuditoria")?.value||""});const d=await api(`/api/auditoria?${params}`);if($("#resultadoAuditoria"))renderAuditoria(d);return d}
async function telaAuditoria(){telaAtual="auditoria";$("#titulo").textContent="Histórico de auditoria";const d=await api("/api/auditoria?pagina=1");$("#conteudo").innerHTML=`<div class="bloco auditoria-bloco"><div class="auditoria-topo"><div><h3>Atividades registradas</h3><p>Consulte alterações realizadas no CRM. Somente administradores têm acesso a este histórico.</p></div></div><div class="auditoria-filtros"><input id="buscaAuditoria" placeholder="Pesquisar usuário, ação ou detalhe"><select id="tipoAuditoria"><option value="">Todos os cadastros</option>${Object.entries(tiposAuditoria).map(([v,t])=>`<option value="${v}">${t}</option>`).join("")}</select><select id="usuarioAuditoria"><option value="">Todos os usuários</option>${d.usuarios.map(u=>`<option value="${u.id}">${h(u.nome)}</option>`).join("")}</select><label>De<input id="inicioAuditoria" type="date"></label><label>Até<input id="fimAuditoria" type="date"></label><button id="limparAuditoria" type="button" class="secundario">Limpar filtros</button></div><div id="resultadoAuditoria"></div></div>`;renderAuditoria(d);let timer;$("#buscaAuditoria").oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>carregarAuditoria(1),300)};["#tipoAuditoria","#usuarioAuditoria","#inicioAuditoria","#fimAuditoria"].forEach(id=>$(id).onchange=()=>carregarAuditoria(1));$("#limparAuditoria").onclick=()=>{$("#buscaAuditoria").value="";$("#tipoAuditoria").value="";$("#usuarioAuditoria").value="";$("#inicioAuditoria").value="";$("#fimAuditoria").value="";carregarAuditoria(1)}}
async function telaBackup(){
  telaAtual="backup";
  $("#titulo").textContent="Backup do sistema";
  const d=await api("/api/backup/resumo"),automatico=d.automatico||{},itens=[["Interessados",d.interessados],["Matrículas",d.matriculas],["Responsáveis",d.responsaveis],["Contratos",d.contratos],["Cobranças",d.cobrancas],["Usuários",d.usuarios]],ultimoAutomatico=automatico.ultimo?new Date(automatico.ultimo.criado_em).toLocaleString("pt-BR"):"Nenhuma cópia automática criada ainda";
  $("#conteudo").innerHTML=`<div class="bloco backup-bloco"><div class="backup-topo"><div><h3>Cópia completa dos dados</h3><p>Baixe um arquivo com todos os cadastros atuais do CRM.</p></div><a class="backup-botao" href="/api/backup/download" download>⇩ Baixar backup agora</a></div><div class="backup-resumo">${itens.map(([nome,total])=>`<div><span>${h(nome)}</span><strong>${h(total)}</strong></div>`).join("")}</div><div class="backup-aviso"><b>Guarde este arquivo em local seguro.</b><br>Ele contém dados pessoais de alunos, responsáveis e usuários. Recomendamos gerar uma nova cópia sempre que houver alterações importantes no sistema.</div></div><div class="bloco backup-automatico"><div class="backup-topo"><div><h3>Backup automático</h3><p><span class="backup-estado ${automatico.ativo?"ativo":"desativado"}">${automatico.ativo?"Ativo":"Desativado"}</span> ${automatico.ativo?`Todos os dias às ${h(automatico.horario)}`:"A rotina automática está desativada."}</p></div><button id="executarBackupAutomatico" type="button" ${automatico.ativo?"":"disabled"}>Criar cópia no servidor agora</button></div><div class="backup-auto-info"><b>Última cópia:</b> ${h(ultimoAutomatico)}<br><span>${automatico.ultimo?`Arquivo: ${h(automatico.ultimo.nome)} · `:""}${h(automatico.total||0)} cópia(s) automática(s) armazenada(s)</span></div><small id="mensagemBackupAutomatico"></small><p class="backup-local"><b>Local:</b> pasta <code>backups</code>, dentro da pasta principal do CRM.</p></div><div class="bloco restauracao-bloco"><h3>Restaurar uma cópia anterior</h3><p>Use somente um arquivo JSON gerado por este CRM. Os dados atuais serão substituídos pelos dados existentes no arquivo.</p><label class="arquivo-backup">Selecionar arquivo de backup<input id="arquivoRestauracao" type="file" accept=".json,application/json"></label><div id="resumoRestauracao" class="restauracao-resumo oculto"></div><label class="confirmacao-risco"><input id="entendoRestauracao" type="checkbox"> Entendo que os dados atuais serão substituídos.</label><label class="campo-confirmacao">Para confirmar, digite <b>RESTAURAR</b><input id="textoRestauracao" autocomplete="off" placeholder="RESTAURAR"></label><button id="restaurarBackup" class="botao-perigo" type="button" disabled>Restaurar backup selecionado</button><small id="erroRestauracao"></small><div class="restauracao-protecao"><b>Proteção automática:</b> antes da restauração, o sistema salvará uma cópia completa dos dados atuais na pasta <code>backups</code> do CRM.</div></div>`;
  const arquivo=$("#arquivoRestauracao"),resumo=$("#resumoRestauracao"),entendo=$("#entendoRestauracao"),texto=$("#textoRestauracao"),botao=$("#restaurarBackup"),erro=$("#erroRestauracao");
  const botaoAutomatico=$("#executarBackupAutomatico"),mensagemAutomatico=$("#mensagemBackupAutomatico");
  botaoAutomatico.onclick=async()=>{botaoAutomatico.disabled=true;botaoAutomatico.textContent="Criando cópia...";mensagemAutomatico.textContent="";try{const r=await api("/api/backup/automatico",{method:"POST"});alert(`Backup criado com sucesso em ${r.arquivo.caminho}.`);await telaBackup()}catch(e){mensagemAutomatico.textContent=e.message;botaoAutomatico.textContent="Criar cópia no servidor agora";botaoAutomatico.disabled=false}};
  let backupSelecionado=null;
  const atualizarBotao=()=>{botao.disabled=!(backupSelecionado&&entendo.checked&&texto.value.trim()==="RESTAURAR")};
  entendo.onchange=atualizarBotao;
  texto.oninput=atualizarBotao;
  arquivo.onchange=async()=>{
    backupSelecionado=null;resumo.classList.add("oculto");erro.textContent="";texto.value="";entendo.checked=false;atualizarBotao();
    const selecionado=arquivo.files[0];if(!selecionado)return;
    if(selecionado.size>20*1024*1024){erro.textContent="O arquivo ultrapassa o limite de 20 MB.";arquivo.value="";return}
    try{
      const backup=JSON.parse(await selecionado.text()),tabelas=["usuarios","interessados","interessado_contatos","matriculas","matricula_responsaveis","contratos","cobrancas","historico"];
      if(backup.formato!=="crm-gestao-escolar-backup"||Number(backup.versao)!==1||tabelas.some(t=>!Array.isArray(backup.dados?.[t])))throw new Error("Arquivo inválido ou incompleto.");
      backupSelecionado=backup;
      const total=tabelas.reduce((s,t)=>s+backup.dados[t].length,0),gerado=backup.gerado_em?new Date(backup.gerado_em).toLocaleString("pt-BR"):"Data não informada";
      resumo.innerHTML=`<b>Arquivo verificado:</b> ${h(selecionado.name)}<br><span>Gerado em ${h(gerado)} · ${h(total)} registros no total · ${h(backup.dados.matriculas.length)} matrículas · ${h(backup.dados.cobrancas.length)} cobranças</span>`;
      resumo.classList.remove("oculto");atualizarBotao();
    }catch(e){erro.textContent=e.message||"Não foi possível ler o arquivo.";arquivo.value=""}
  };
  botao.onclick=async()=>{
    if(!backupSelecionado||botao.disabled)return;
    if(!confirm("ATENÇÃO: esta operação substituirá os dados atuais pelos dados do backup. Deseja continuar?"))return;
    botao.disabled=true;botao.textContent="Restaurando com segurança...";erro.textContent="";
    try{const r=await api("/api/backup/restaurar",{method:"POST",body:JSON.stringify({confirmacao:texto.value.trim(),backup:backupSelecionado})});alert(`Backup restaurado com sucesso.\n\nA cópia de segurança dos dados anteriores foi salva em: ${r.arquivo_seguranca}`);await telaBackup()}catch(e){erro.textContent=e.message;botao.textContent="Restaurar backup selecionado";atualizarBotao()}
  };
}
async function telaRede(){
  telaAtual="rede";
  $("#titulo").textContent="Sistema e rede";
  const d=await api("/api/sistema/rede"),enderecos=d.enderecos_rede||[];
  $("#conteudo").innerHTML=`<div class="bloco"><h3>Acesso ao CRM na rede da escola</h3><p>Use um dos endereços abaixo em outro computador conectado ao mesmo Wi-Fi ou cabo de rede.</p><div class="rede-grade"><div class="rede-cartao"><span>Versão ativa</span><strong>${h(d.versao||"Anterior")}</strong></div><div class="rede-cartao"><span>Computador principal</span><strong>${h(d.computador)}</strong></div><div class="rede-cartao"><span>Porta do sistema</span><strong>${h(d.porta)}</strong></div></div><div class="rede-enderecos">${enderecos.length?enderecos.map(url=>`<div class="rede-endereco"><code>${h(url)}</code><button type="button" data-copiar-rede="${h(url)}">Copiar endereço</button></div>`).join(""):'<div class="rede-alerta">Nenhum endereço de rede foi identificado. Confirme se o computador principal está conectado ao Wi-Fi ou ao cabo de rede.</div>'}</div><small id="mensagemRede"></small><div class="rede-seguranca"><b>Proteção do login ativa:</b> após ${h(d.protecao_login.max_tentativas)} tentativas incorretas, o acesso fica bloqueado por ${h(d.protecao_login.bloqueio_minutos)} minutos.</div></div><div class="bloco"><h3>Como testar em outro computador</h3><ol class="rede-passos"><li>Mantenha este computador ligado e o CRM aberto pelo atalho.</li><li>Conecte o outro computador à mesma rede da escola.</li><li>Abra o Chrome ou Edge e digite um dos endereços apresentados acima.</li><li>Entre usando o usuário, CPF ou e-mail e a senha cadastrada no CRM.</li></ol><div class="rede-alerta"><b>Se a página não abrir:</b> no computador principal, permita o aplicativo <b>Node.js</b> nas redes privadas do Firewall do Windows. Não marque rede pública e não encaminhe a porta no roteador.</div></div>`;
  $("#conteudo").onclick=async e=>{
    const botao=e.target.closest("[data-copiar-rede]");if(!botao)return;
    const texto=botao.dataset.copiarRede,mensagem=$("#mensagemRede");
    try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(texto);else throw new Error();mensagem.textContent="Endereço copiado."}catch{const campo=document.createElement("textarea");campo.value=texto;campo.style.position="fixed";campo.style.opacity="0";document.body.appendChild(campo);campo.select();document.execCommand("copy");campo.remove();mensagem.textContent="Endereço copiado."}
  };
}
